class Pile:
    def __init__(self):
        self.data = []

    def est_vide(self):
        return len(self.data) == 0       

    def empile(self,x):
        self.data.append(x)

    def depile(self):
        if self.est_vide():
            return None
        else :
            return self.data.pop()

    def affiche(self):
        p_temp = Pile()
        print('---')
        while not self.est_vide():
            v = self.depile()
            print('|' + str(v) + '|')
            p_temp.empile(v)
        print('---')
        while not p_temp.est_vide():
            self.empile(p_temp.depile())
```

